jsonTools.init:
function init(eli) {
  // ELI Agent: Address Comments (Email-to-Redline; tools/eli_agent parts 20 and 55) in a bundle of its own, on Revise's
  // engine (docs/ELI_AGENT_SPLIT_PLAN.md step 5). The host hands over its helpers (H); Revise, in its area, the engine
  // below. Beside an older ELI Agent that still holds the engine itself, the engine comes from its H. Missing any
  // piece (no Revise yet, or a host that hands over neither) this bundle does nothing until it starts again.
  var H = typeof eli.dispatch === "function" ? eli.dispatch("eli_agent", "host") : null;
  var RV = H && H.fn && typeof H.fn._egFrom === "function" ? H.fn._egFrom("revise") : null;
  // Starts again beside a newer ELI Agent (an update installed while ELI was open), or when Revise arrives; this copy
  // then stops listening (and ignores an event already on its way to it).
  var gone = false, subs = [];
  var off = function () { gone = true; subs.forEach(function (u) { if (typeof u === "function") u(); }); subs = []; };
  if (eli.bus && typeof eli.bus.on === "function") {
    subs.push(eli.bus.on("eli_agent:host", function (e) {
      if (gone || !e || !e.host || e.host === H) return;
      off();
      init(eli);
    }));
    subs.push(eli.bus.on("eli_agent:revise", function () {
      var now = H && H.fn && typeof H.fn._egFrom === "function" ? H.fn._egFrom("revise") : null;
      if (gone || !now || now === RV) return;
      off();
      init(eli);
    }));
  }
  if (!H || !(H.apiVersion >= 1) || !H.fn) return;
  var E = RV || H.fn;   // the engine: Revise's, or an older host's own
  var _aiJsonCall = H.fn._aiJsonCall, _aiTextCall = H.fn._aiTextCall, _bodyHeader = H.fn._bodyHeader,
    _closeAgentOverlay = H.fn._closeAgentOverlay, _egArea = H.fn._egArea, _egRun = H.fn._egRun,
    _egScreen = H.fn._egScreen, _esc = H.fn._esc, _getAgentSettings = H.fn._getAgentSettings,
    _loadPlaybookSnippets = H.fn._loadPlaybookSnippets, _renderOverlayBody = H.fn._renderOverlayBody,
    _stageStrip = H.fn._stageStrip, _toast = H.fn._toast, _wireCancelOnly = H.fn._wireCancelOnly,
    _composeSummary = E._composeSummary, _ensureQaIndex = E._ensureQaIndex,
    _guardProposedEdits = E._guardProposedEdits, _resolveConflicts = E._resolveConflicts,
    _runBucketPasses = E._runBucketPasses, _runCritiquePass = E._runCritiquePass,
    _runProposalAudit = E._runProposalAudit, _startEnrichment = E._startEnrichment, _validateEdits = E._validateEdits,
    _rvTeamSpec = E._rvTeamSpec;   // [TEAM] Revise's team, led by Address Comments
  if ([_aiJsonCall, _aiTextCall, _bodyHeader, _closeAgentOverlay, _egArea, _egRun, _egScreen, _esc, _getAgentSettings,
    _loadPlaybookSnippets, _renderOverlayBody, _stageStrip, _toast, _wireCancelOnly, _composeSummary, _ensureQaIndex,
    _guardProposedEdits, _resolveConflicts, _runBucketPasses, _runCritiquePass, _runProposalAudit, _startEnrichment,
    _validateEdits, _rvTeamSpec].indexOf(undefined) >= 0) return;

  // ─── Email-to-Redline: compose pane ──────────────────────────────
  // Four input methods, all routed to _egRun().commentSource:
  //   1. 📋 paste from clipboard
  //   2. textarea
  //   3. drop a file (.txt / .eml / .docx — last requires JSZip)
  //   4. read this doc's native Word comments
  // All sources concatenate. User can mix.
  function _bodyCompose() {
    var src = _esc(_egRun().commentSource || "");
    return _bodyHeader() +
      '<div class="_eg_compose_hint">How do you want to bring in the comments? Use any combination of the methods below.</div>' +
      // 1. Clipboard
      '<div class="_eg_compose_method">' +
        '<div class="_eg_compose_method_head">Clipboard</div>' +
        '<button id="_eg_paste_clip" type="button" class="_eg_btn_secondary">📋 Paste from clipboard</button>' +
      '</div>' +
      // 2. Textarea
      '<div class="_eg_compose_method">' +
        '<div class="_eg_compose_method_head">Paste / type the comments</div>' +
        '<textarea id="_eg_compose_textarea" class="_eg_compose_textarea" rows="8" placeholder="Paste the email body, redline notes, or comment thread here. Multiple paragraphs OK. The agent will parse out each individual comment.">' + src + '</textarea>' +
      '</div>' +
      // 3. File drop
      '<div class="_eg_compose_method">' +
        '<div class="_eg_compose_method_head">Drop a file (.txt, .eml, .docx)</div>' +
        '<div id="_eg_drop_zone" class="_eg_drop_zone" tabindex="0">' +
          '<div>📎 Drag a file here, or <button id="_eg_file_browse" type="button" class="_eg_link_btn">browse</button></div>' +
          '<input id="_eg_file_input" type="file" accept=".txt,.eml,.md,.docx" style="display:none;" />' +
        '</div>' +
      '</div>' +
      // 4. Word comments
      '<div class="_eg_compose_method">' +
        '<div class="_eg_compose_method_head">This document\'s Word comments</div>' +
        '<button id="_eg_read_comments" type="button" class="_eg_btn_secondary">📝 Read this doc\'s comments</button>' +
        '<span id="_eg_read_comments_status" class="_eg_compose_meta"></span>' +
      '</div>' +
      '<div class="_eg_actions_row _eg_actions_sticky">' +
        '<button id="_eg_close_compose" type="button" class="_eg_btn_secondary">Cancel</button>' +
        '<button id="_eg_compose_continue" type="button" class="_eg_btn_primary _eg_btn_apply" ' +
          (_egRun().commentSource && _egRun().commentSource.trim().length ? '' : 'disabled') + '>Plan Edits →</button>' +
      '</div>';
  }
  function _wireComposeControls(body) {
    function _refreshContinueBtn() {
      var btn = body.querySelector("#_eg_compose_continue");
      if (!btn) return;
      btn.disabled = !(_egRun().commentSource && _egRun().commentSource.trim().length);
    }
    function _appendSource(text, label) {
      if (!text) return;
      var prefix = _egRun().commentSource ? _egRun().commentSource.replace(/\s+$/, "") + "\n\n--- " + (label || "added") + " ---\n" : "";
      _egRun().commentSource = prefix + text;
      var ta = body.querySelector("#_eg_compose_textarea");
      if (ta) ta.value = _egRun().commentSource;
      _refreshContinueBtn();
    }
    var ta = body.querySelector("#_eg_compose_textarea");
    if (ta) {
      ta.oninput = function () {
        _egRun().commentSource = ta.value;
        _refreshContinueBtn();
      };
    }
    var pasteBtn = body.querySelector("#_eg_paste_clip");
    if (pasteBtn) pasteBtn.onclick = function () {
      if (!navigator.clipboard || typeof navigator.clipboard.readText !== "function") {
        _toast("Clipboard read isn't available in this browser — paste manually below.", "warn");
        return;
      }
      navigator.clipboard.readText().then(function (txt) {
        if (txt) _appendSource(txt, "from clipboard");
        else _toast("Clipboard is empty.", "info");
      }).catch(function (err) {
        _toast("Couldn't read clipboard: " + (err && err.message), "err");
      });
    };
    var fileInput = body.querySelector("#_eg_file_input");
    var browseBtn = body.querySelector("#_eg_file_browse");
    if (browseBtn) browseBtn.onclick = function () { if (fileInput) fileInput.click(); };
    if (fileInput) fileInput.onchange = function () {
      var f = fileInput.files && fileInput.files[0];
      if (f) _readCommentFile(f).then(function (txt) {
        if (txt) _appendSource(txt, "file: " + f.name);
      });
    };
    var dropZone = body.querySelector("#_eg_drop_zone");
    if (dropZone) {
      dropZone.ondragover = function (ev) { ev.preventDefault(); dropZone.classList.add("_eg_drop_active"); };
      dropZone.ondragleave = function () { dropZone.classList.remove("_eg_drop_active"); };
      dropZone.ondrop = function (ev) {
        ev.preventDefault();
        dropZone.classList.remove("_eg_drop_active");
        var f = ev.dataTransfer && ev.dataTransfer.files && ev.dataTransfer.files[0];
        if (f) _readCommentFile(f).then(function (txt) {
          if (txt) _appendSource(txt, "file: " + f.name);
        });
      };
    }
    var readCommentsBtn = body.querySelector("#_eg_read_comments");
    var readCommentsStatus = body.querySelector("#_eg_read_comments_status");
    if (readCommentsBtn) readCommentsBtn.onclick = function () {
      readCommentsBtn.disabled = true;
      var orig = readCommentsBtn.textContent;
      readCommentsBtn.textContent = "Reading…";
      _readDocComments().then(function (txt) {
        readCommentsBtn.disabled = false;
        readCommentsBtn.textContent = orig;
        if (txt) {
          _appendSource(txt, "Word comments");
          if (readCommentsStatus) readCommentsStatus.textContent = "✓ added";
        } else {
          if (readCommentsStatus) readCommentsStatus.textContent = "no comments found";
        }
      }).catch(function (err) {
        readCommentsBtn.disabled = false;
        readCommentsBtn.textContent = orig;
        if (readCommentsStatus) readCommentsStatus.textContent = "failed: " + (err && err.message);
      });
    };
    var continueBtn = body.querySelector("#_eg_compose_continue");
    if (continueBtn) continueBtn.onclick = function () {
      if (!_egRun().commentSource || !_egRun().commentSource.trim()) return;
      _runEmailAgentPipeline();
    };
    var cancelBtn = body.querySelector("#_eg_close_compose");
    if (cancelBtn) cancelBtn.onclick = _closeAgentOverlay;
  }
  // Read a file the user dropped/browsed. Routes based on extension.
  function _readCommentFile(file) {
    if (!file) return Promise.resolve("");
    var name = String(file.name || "").toLowerCase();
    if (name.endsWith(".docx")) return _readDocxFile(file);
    // .eml / .txt / .md — all just text.
    return new Promise(function (resolve) {
      var reader = new FileReader();
      reader.onload = function () {
        var txt = String(reader.result || "");
        // Strip EML headers (everything before the first blank line).
        if (name.endsWith(".eml")) {
          var blank = txt.indexOf("\r\n\r\n");
          if (blank === -1) blank = txt.indexOf("\n\n");
          if (blank !== -1) txt = txt.slice(blank + 2);
        }
        resolve(txt);
      };
      reader.onerror = function () { resolve(""); };
      reader.readAsText(file);
    });
  }
  function _readDocxFile(file) {
    // .docx is a zip — parse word/document.xml + word/comments.xml.
    if (typeof window.JSZip !== "function") {
      _toast(".docx parsing needs JSZip — falling back to plain text.", "warn");
      return new Promise(function (resolve) {
        var reader = new FileReader();
        reader.onload = function () { resolve(String(reader.result || "")); };
        reader.onerror = function () { resolve(""); };
        reader.readAsText(file);
      });
    }
    return new Promise(function (resolve) {
      var reader = new FileReader();
      reader.onload = function () {
        window.JSZip.loadAsync(reader.result).then(function (zip) {
          var commentsFile = zip.file("word/comments.xml");
          var documentFile = zip.file("word/document.xml");
          var commentsPromise = commentsFile ? commentsFile.async("string") : Promise.resolve("");
          var documentPromise = documentFile ? documentFile.async("string") : Promise.resolve("");
          return Promise.all([commentsPromise, documentPromise]);
        }).then(function (parts) {
          var commentsXml = parts[0];
          var docXml = parts[1];
          var out = "";
          if (commentsXml) {
            // Extract comment text from <w:comment> elements.
            var commentMatches = commentsXml.match(/<w:comment\b[^>]*>[\s\S]*?<\/w:comment>/g) || [];
            commentMatches.forEach(function (block) {
              var authorMatch = block.match(/w:author="([^"]+)"/);
              var author = authorMatch ? authorMatch[1] : "Unknown";
              var textMatches = block.match(/<w:t[^>]*>([^<]*)<\/w:t>/g) || [];
              var text = textMatches.map(function (t) {
                return t.replace(/<w:t[^>]*>/, "").replace(/<\/w:t>/, "");
              }).join("");
              if (text) out += author + ": " + text + "\n\n";
            });
          }
          if (docXml) {
            // Extract body paragraphs as plain text.
            var paraMatches = docXml.match(/<w:p\b[^>]*>[\s\S]*?<\/w:p>/g) || [];
            var bodyText = paraMatches.map(function (p) {
              var textMatches = p.match(/<w:t[^>]*>([^<]*)<\/w:t>/g) || [];
              return textMatches.map(function (t) {
                return t.replace(/<w:t[^>]*>/, "").replace(/<\/w:t>/, "");
              }).join("");
            }).filter(Boolean).join("\n");
            if (bodyText) out += "\n--- BODY TEXT ---\n" + bodyText;
          }
          resolve(out);
        }).catch(function (err) {
          _toast("Couldn't parse .docx: " + (err && err.message), "err");
          resolve("");
        });
      };
      reader.onerror = function () { resolve(""); };
      reader.readAsArrayBuffer(file);
    });
  }
  // Extract Word comments from the open doc via Office.js.
  function _readDocComments() {
    if (!eli.host || typeof eli.host.runRaw !== "function") return Promise.resolve("");
    return eli.host.runRaw("eli_agent:read_comments", function (context) {
      var comments = context.document.body.getComments();
      comments.load("items/content,items/authorName");
      return context.sync().then(function () {
        var items = comments.items || [];
        if (!items.length) return "";
        return items.map(function (c) {
          var author = c.authorName || "Unknown";
          var content = String(c.content || "").trim();
          if (!content) return "";
          return author + ": " + content;
        }).filter(Boolean).join("\n\n");
      });
    }).catch(function () { return ""; });
  }

  // ─── Email-to-Redline: parsing comments stage ────────────────────
  function _bodyParsingComments() {
    return _bodyHeader() +
      _stageStrip("strategy") +  // parse-comments shares the strategy slot
      '<div class="_eg_status_box">' +
        '<div class="_eg_status_dot"></div>' +
        '<div>Parsing the email/comment thread into structured items…</div>' +
      '</div>' +
      '<div class="_eg_actions_row">' +
        '<button id="_eg_cancel_plan" type="button" class="_eg_btn_secondary">Cancel</button>' +
      '</div>';
  }

  // ─── Email-to-Redline: confirm parsed comments ───────────────────
  function _bodyConfirmComments() {
    var comments = _egRun().parsedComments || [];
    var rows = comments.map(function (c) {
      var skipped = c.skipped ? " _eg_comment_skipped" : "";
      var sev = c.severity || "med";
      return '<div class="_eg_comment_row' + skipped + '" data-eg-comment-id="' + _esc(c.id) + '">' +
        '<div class="_eg_comment_head">' +
          '<label class="_eg_comment_toggle">' +
            '<input type="checkbox" data-eg-comment-skip="' + _esc(c.id) + '" ' + (c.skipped ? "" : "checked") + ' />' +
            '<span>' + (c.skipped ? "Skipped" : "Include") + '</span>' +
          '</label>' +
          '<span class="_eg_comment_sev _eg_comment_sev_' + _esc(sev) + '">' + _esc(sev.toUpperCase()) + '</span>' +
          (c.author ? '<span class="_eg_comment_author">' + _esc(c.author) + '</span>' : '') +
          (c.scope ? '<span class="_eg_comment_scope">' + _esc(c.scope) + '</span>' : '') +
        '</div>' +
        '<div class="_eg_comment_ask"><strong>Ask:</strong> ' + _esc(c.ask || "") + '</div>' +
        (c.originalText
          ? '<details class="_eg_comment_orig"><summary>Original text</summary><div>' + _esc(c.originalText) + '</div></details>'
          : '') +
      '</div>';
    }).join("");
    var keepCount = comments.filter(function (c) { return !c.skipped; }).length;
    return _bodyHeader() +
      _stageStrip("buckets") +
      '<div class="_eg_section_label">PARSED ' + comments.length + ' COMMENTS</div>' +
      '<div class="_eg_compose_hint">Review what I parsed. Uncheck any I should skip, then continue to generate edits.</div>' +
      (rows || '<div class="_eg_empty_box">No comments were parsed. Go back and provide more text.</div>') +
      '<div class="_eg_actions_row _eg_actions_sticky">' +
        '<button id="_eg_back_to_compose" type="button" class="_eg_btn_secondary">← Back</button>' +
        '<button id="_eg_proceed_to_plan" type="button" class="_eg_btn_primary _eg_btn_apply" ' + (keepCount ? '' : 'disabled') + '>Generate ' + keepCount + ' Edit Set' + (keepCount === 1 ? "" : "s") + ' →</button>' +
      '</div>';
  }
  function _wireConfirmCommentsControls(body) {
    body.querySelectorAll("[data-eg-comment-skip]").forEach(function (cb) {
      cb.onchange = function () {
        var id = cb.getAttribute("data-eg-comment-skip");
        var c = (_egRun().parsedComments || []).find(function (x) { return x.id === id; });
        if (c) c.skipped = !cb.checked;
        _renderOverlayBody();
      };
    });
    var backBtn = body.querySelector("#_eg_back_to_compose");
    if (backBtn) backBtn.onclick = function () {
      _egRun().status = "compose";
      _renderOverlayBody();
    };
    var proceedBtn = body.querySelector("#_eg_proceed_to_plan");
    if (proceedBtn) proceedBtn.onclick = function () {
      _continueEmailAgentAfterConfirmation();
    };
  }

  // ─── Email-to-Redline: drafting response email ───────────────────
  function _bodyDraftingEmail() {
    return _bodyHeader() +
      '<div class="_eg_status_box">' +
        '<div class="_eg_status_dot"></div>' +
        '<div>Drafting your response email…</div>' +
      '</div>' +
      '<div class="_eg_actions_row">' +
        '<button id="_eg_cancel_plan" type="button" class="_eg_btn_secondary">Cancel</button>' +
      '</div>';
  }
  function _bodyResponseEmail() {
    var email = _egRun().responseEmail || "";
    return _bodyHeader() +
      '<div class="_eg_section_label">📧 RESPONSE EMAIL DRAFT</div>' +
      '<div class="_eg_compose_hint">Copy this and paste into Outlook. Adjust as needed.</div>' +
      '<textarea id="_eg_email_textarea" class="_eg_compose_textarea" rows="14">' + _esc(email) + '</textarea>' +
      '<div class="_eg_actions_row _eg_actions_sticky">' +
        '<button id="_eg_email_back" type="button" class="_eg_btn_secondary">← Back to applied edits</button>' +
        '<button id="_eg_email_copy" type="button" class="_eg_btn_primary">📋 Copy to clipboard</button>' +
      '</div>';
  }
  function _wireResponseEmailControls(body) {
    var backBtn = body.querySelector("#_eg_email_back");
    if (backBtn) backBtn.onclick = function () {
      _egRun().status = "applied";
      _renderOverlayBody();
    };
    var copyBtn = body.querySelector("#_eg_email_copy");
    if (copyBtn) copyBtn.onclick = function () {
      var ta = body.querySelector("#_eg_email_textarea");
      var text = ta ? ta.value : (_egRun().responseEmail || "");
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(text).then(function () {
          var orig = copyBtn.textContent;
          copyBtn.textContent = "✓ Copied";
          setTimeout(function () { copyBtn.textContent = orig; }, 1400);
        });
      } else {
        if (ta) { ta.select(); document.execCommand("copy"); }
      }
    };
  }
  // [SCREENS] this area's overlay screens (status → body, wiring).
  _egScreen("compose",           _bodyCompose,         _wireComposeControls);
  _egScreen("parsing_comments",  _bodyParsingComments, _wireCancelOnly);
  _egScreen("confirm_comments",  _bodyConfirmComments, _wireConfirmCommentsControls);
  _egScreen("drafting_email",    _bodyDraftingEmail,   _wireCancelOnly);
  _egScreen("response_email",    _bodyResponseEmail,   _wireResponseEmailControls);

  // ─── Email-to-Redline pipeline (variant of _runPlan) ─────────────
  // After the compose pane finishes:
  //   1. parsing_comments  — Pass 0: parse raw email/blob into structured comments
  //   2. confirm_comments  — UI checkpoint; user confirms / skips
  //   3. capturing         — warm QA index
  //   4. buckets           — per-comment edit generation (one AI call per kept comment)
  //   5. critique          — same as Revise agent
  //   6. enrichment        — proactive findings
  //   7. review (grouped by comment)
  // Called from the compose pane's "Plan Edits →" button.
  // [TEAM] The agent team over Address Comments' waiting screens (the owner, 10-22: "bring the GUI into the other
  // agents"): Revise's team — its engine is Revise's — led by Address Comments, with Comments (what they asked, read
  // from the email first) and Reply (your answer to them, drafted at the end). Needs a Revise that hands its team over.
  function _emTeamSpec() {
    var base = typeof _rvTeamSpec === "function" ? _rvTeamSpec() : null;
    if (!base || !base.team) return null;
    var cut = function (x, n) { var s = String(x == null ? "" : x).replace(/\s+/g, " ").trim(); return s.length > n ? s.slice(0, n - 1).replace(/\s+\S*$/, "") + "…" : s; };
    base.team.lead = { id: "AC", name: "Address Comments", role: "Lead agent", icon: "note" };
    base.team.agents = [{ id: "CM", name: "Comments", role: "What they asked", icon: "quotes", senior: true }].concat(base.team.agents,
      [{ id: "RE", name: "Reply", role: "Your answer to them", icon: "note" }]);
    // Revise's own steps and lines are its lead's ("RV"): here they are Address Comments' (an id the team doesn't have is dropped)
    Object.keys(base.steps).forEach(function (k) { if (base.steps[k].agent === "RV") base.steps[k].agent = "AC"; });
    base.steps.drafting_email = { agent: "RE", label: "Drafting your reply" };
    base.prelude = { parsing_comments: ["Initializing agents", "Defining roles", "Reading the comments"], capturing: ["Reading the document", "Loading the playbook"] };
    base.folded.confirm_comments = "Their comments";
    base.folded.response_email = "Your reply";
    var found = base.found;
    base.found = function (run) {
      var out = (run.parsedComments || []).filter(function (c) { return !c.skipped; }).slice(0, 12).map(function (c) {
        return { key: "cm" + c.id, agent: "CM", item: { art: cut(c.scope || c.author || "Comment", 40), clause: "", status: "note", text: cut(c.ask, 90) } };
      }).concat(found(run).map(function (x) { return x.agent === "RV" ? Object.assign({}, x, { agent: "AC" }) : x; }));
      if (run.status === "drafting_email") out.push({ key: "re", agent: "RE", item: { art: "Your reply", clause: "", status: "read", text: "Drafting your reply to their comments" } });
      return out;
    };
    return base;
  }
  function _runEmailAgentPipeline() {
    if (!_egRun()) return Promise.resolve();
    if (!_egRun().commentSource || !_egRun().commentSource.trim()) return Promise.resolve();
    _egRun().teamSpec = _emTeamSpec();   // [TEAM]
    _egRun().status = "parsing_comments";
    _renderOverlayBody();
    var prompt = _buildParseCommentsPrompt(_egRun());
    return _aiJsonCall(prompt, { comments: "object" })
      .then(function (result) {
        if (!_egRun()) return;
        var comments = (result && Array.isArray(result.comments)) ? result.comments : [];
        // Normalize each parsed comment.
        var seenIds = {};
        var normalized = [];
        comments.forEach(function (c, idx) {
          if (!c || typeof c !== "object") return;
          var id = String(c.id || ("c" + (idx + 1)));
          if (seenIds[id]) id = id + "_" + idx;
          seenIds[id] = true;
          if (!c.ask || typeof c.ask !== "string" || !c.ask.trim()) return;
          var sev = (c.severity === "high" || c.severity === "must-fix" || c.severity === "med" || c.severity === "low" || c.severity === "nit")
            ? c.severity : "med";
          normalized.push({
            id: id,
            author: typeof c.author === "string" ? c.author : "",
            scope: typeof c.scope === "string" ? c.scope : "",
            ask: c.ask.trim(),
            severity: sev,
            originalText: typeof c.originalText === "string" ? c.originalText : "",
            skipped: false,
          });
        });
        _egRun().parsedComments = normalized;
        _egRun().status = "confirm_comments";
        _renderOverlayBody();
        eli.log.event("tool", "eli_agent_comments_parsed", { count: normalized.length });
      })
      .catch(function (err) {
        if (!_egRun()) return;
        _egRun().status = "error";
        _egRun().error = (err && err.message) || String(err);
        _renderOverlayBody();
      });
  }
  // After the user confirms which parsed comments to address, fold into
  // the normal pipeline. Comments become "buckets". Everything from
  // capture-index onward is the same as Revise agent.
  function _continueEmailAgentAfterConfirmation() {
    if (!_egRun()) return Promise.resolve();
    _egRun().status = "capturing";
    _egRun().plan = { summary: "", edits: [], unrequested: [] };
    _egRun().bucketProgress = {};
    _egRun().acceptance = {};
    _renderOverlayBody();
    return _ensureQaIndex().then(function (idx) {
      if (!_egRun()) return;
      _egRun().qaIndex = idx.qaIndex || [];
      _egRun().docHash = idx.docHash || null;
      _egRun().indexSource = idx.source || "unknown";
      if (!_egRun().qaIndex.length) {
        throw new Error("Document index is empty — open the doc you want to revise.");
      }
      return Promise.all([
        _getAgentSettings(_egRun().agent),
        _loadPlaybookSnippets(),
      ]);
    }).then(function (results) {
      if (!_egRun()) return;
      _egRun().settings = results[0];
      _egRun().playbooks = results[1] || [];
      // Convert kept comments to bucket-shape so _runBucketPasses can reuse.
      var kept = (_egRun().parsedComments || []).filter(function (c) { return !c.skipped; });
      var buckets = kept.map(function (c) {
        return {
          name: c.id + ": " + (c.scope || c.author || "comment"),
          focus: c.ask,
          scope: c.scope || "any",
          commentRef: c,  // attached for per-comment prompt to access original text + linkage
        };
      });
      _egRun().strategy = { summary: "Addressing " + kept.length + " comment(s).", buckets: buckets };
      _egRun().status = "buckets";
      _renderOverlayBody();
      return _runBucketPasses(buckets);
    }).then(function (allEdits) {
      if (!_egRun()) return;
      _egRun().plan.edits = _validateEdits(allEdits);
      _egRun().plan.summary = _composeSummary(_egRun().strategy, _egRun().plan.edits);
      _egRun().status = "critique";
      _renderOverlayBody();
      return _runCritiquePass(_egRun().plan.edits);
    }).then(function (refined) {
      if (!_egRun()) return;
      _egRun().plan.edits = _validateEdits(refined);
      // Same audit as the revise pipeline — two comments asking for the
      // same change produce the same overlapping proposals.
      _egRun().status = "auditing";
      _renderOverlayBody();
      return _resolveConflicts()
        .then(function (out) { return _runProposalAudit(out); })
        .then(function (out) { return _guardProposedEdits(out); })
        .then(function (out) { if (_egRun()) _egRun().conflicts = out; });
    }).then(function () {
      if (!_egRun()) return;
      // Enrichment runs alongside the review, not in front of it — same
      // reason as the instruction path above.
      _egRun().plan.unrequested = [];
      _startEnrichment(_egRun());
      _egRun().acceptance = {};
      _egRun().plan.edits.forEach(function (e) { _egRun().acceptance[e.id] = "pending"; });
      _egRun().status = "review";
      _renderOverlayBody();
    }).catch(function (err) {
      if (!_egRun()) return;
      if (err && (err.name === "AbortError" || /cancel/i.test(String(err.message)))) return;
      _egRun().status = "error";
      _egRun().error = (err && err.message) || String(err);
      _renderOverlayBody();
    });
  }

  // ─── Response email generation (final email-agent step) ─────────
  // Takes the parsed comments + applied edits + failures and produces
  // an email-style summary for the user to paste back to whoever sent
  // the comments. Stays in the agent overlay (status: response_email).
  function _runResponseEmailGeneration() {
    if (!_egRun()) return;
    _egRun().status = "drafting_email";
    _renderOverlayBody();
    var prompt = _buildResponseEmailPrompt(_egRun());
    _egRun().cancelToken = (eli.cancel && typeof eli.cancel.token === "function")
      ? eli.cancel.token() : null;
    return _aiTextCall(prompt).then(function (text) {
      if (!_egRun()) return;
      _egRun().responseEmail = String(text || "").trim();
      _egRun().status = "response_email";
      _egRun().cancelToken = null;
      _renderOverlayBody();
      eli.log.event("tool", "eli_agent_response_email_drafted", { length: _egRun().responseEmail.length });
    }).catch(function (err) {
      if (!_egRun()) return;
      _egRun().status = "applied";
      _egRun().cancelToken = null;
      _renderOverlayBody();
      _toast("Couldn't draft response email: " + (err && err.message), "err");
    });
  }
  function _buildResponseEmailPrompt(active) {
    var comments = active.parsedComments || [];
    var applied = (active.applyResult && active.applyResult.appliedEdits) || [];
    var failures = (active.applyResult && active.applyResult.failures) || [];
    var rejected = (active.plan && active.plan.edits || []).filter(function (e) {
      return active.acceptance[e.id] === "rejected";
    });
    // Build per-comment outcome summary.
    var commentOutcomes = comments.map(function (c) {
      if (c.skipped) return { id: c.id, status: "skipped", author: c.author, ask: c.ask, edits: [] };
      var matchingApplied = applied.filter(function (e) { return e.addressesComment === c.id; });
      var matchingRejected = rejected.filter(function (e) { return e.addressesComment === c.id; });
      var matchingFailed = failures.filter(function (f) { return f.edit && f.edit.addressesComment === c.id; });
      var status =
        matchingApplied.length > 0 ? "addressed" :
        matchingFailed.length > 0 ? "blocked" :
        matchingRejected.length > 0 ? "declined" :
        "punted";
      return {
        id: c.id, status: status, author: c.author, scope: c.scope, ask: c.ask,
        editsApplied: matchingApplied.length, editsFailed: matchingFailed.length, editsRejected: matchingRejected.length,
      };
    });
    var primaryAuthor = comments.length && comments[0].author ? comments[0].author : "there";
    return [
      "You are drafting a brief, professional response email to a colleague who sent comments on a contract.",
      "The email summarizes which of their comments were addressed, which were punted, which were blocked.",
      "Tone: collegial, concise, no legalese. 4-8 lines max body. Use bullet points for the per-comment recap.",
      "",
      "OUTPUT: just the email body text — no subject line, no greeting if it would feel forced. Start with \"Hi " + primaryAuthor + ",\" or similar if appropriate.",
      "",
      "═══ ORIGINAL COMMENTS RECEIVED ═══",
      JSON.stringify(comments.map(function (c) {
        return { id: c.id, author: c.author, scope: c.scope, ask: c.ask };
      }), null, 1),
      "",
      "═══ OUTCOMES ═══",
      JSON.stringify(commentOutcomes, null, 1),
      "",
      "FORMAT GUIDE:",
      "- For 'addressed': \"✓ §X — [brief description of edit landed]\"",
      "- For 'punted': \"⚠ Topic — [why I'm flagging back instead of editing]\"",
      "- For 'blocked': \"❌ §X — [what I couldn't find / why]\"",
      "- For 'declined': \"⚪ §X — chose not to make this change [if you want to share reasoning]\"",
      "",
      "End with a 1-line close like \"Redlines attached. Let me know.\"",
    ].join("\n");
  }
  // Parse-comments prompt. Pass 0 of the email agent.
  function _buildParseCommentsPrompt(active) {
    return [
      "You are receiving a raw blob of feedback on a legal document. Could be an email, a comment thread, Word comments, or all of the above.",
      "Parse it into structured comments. Each individual ask becomes one comment object.",
      "Return JSON only.",
      "",
      "OUTPUT SHAPE (example):",
      "{",
      "  \"comments\": [",
      "    {",
      "      \"id\": \"c1\",",
      "      \"author\": \"Sarah\",",
      "      \"scope\": \"§4.2 Payment Terms\",",
      "      \"ask\": \"Extend payment from 30 to 60 days\",",
      "      \"severity\": \"must-fix\",",
      "      \"originalText\": \"Sarah: 'Payment in 30 days is too aggressive — let's push to 60.'\"",
      "    }",
      "  ]",
      "}",
      "",
      "RULES:",
      "1. id: c1, c2, c3… (unique, sequential).",
      "2. author: best guess from the text. Leave empty if unclear.",
      "3. scope: what part of the doc this is about (section, clause, topic). Leave empty if doc-wide.",
      "4. ask: ONE specific thing the commenter wants. If they raise multiple issues in one paragraph, split into multiple comments.",
      "5. severity: 'must-fix' (substantive), 'med' (worth addressing), 'low' (nit), 'high' (critical).",
      "6. originalText: a verbatim quote (≤200 chars) of the relevant excerpt for trace-back.",
      "7. Don't include greetings, sign-offs, or chit-chat as comments — only substantive asks.",
      "",
      "═══ RAW FEEDBACK ═══",
      active.commentSource,
    ].join("\n");
  }
  // [AREAS] What the rest of ELI Agent calls in Email-to-Redline: the applied screen's "Generate response email".
  _egArea("email", { _runResponseEmailGeneration: _runResponseEmailGeneration });
}
